def transform(g):
    h,w=len(g),len(g[0]); o=[r[:] for r in g]
    def d2(r,c): return 0<=r<h and 0<=c<w and g[r][c]==2
    R,L,B,Tp=set(),set(),set(),set()
    for r in range(h):
        for c in range(w):
            if g[r][c]!=2: continue
            ul,ur,dl,dr=d2(r-1,c-1),d2(r-1,c+1),d2(r+1,c-1),d2(r+1,c+1)
            if ul and dl and not ur and not dr: R.add((r,c))
            if ur and dr and not ul and not dl: L.add((r,c))
            if ul and ur and not dl and not dr: B.add((r,c))
            if dl and dr and not ul and not ur: Tp.add((r,c))
    for (r,c) in R:
        for c2 in range(c+1,w):
            if (r,c2) in L and all(g[r][k]==0 for k in range(c+1,c2)):
                for k in range(c+1,c2): o[r][k]=1
                break
            if g[r][c2]!=0: break
    for (r,c) in B:
        for r2 in range(r+1,h):
            if (r2,c) in Tp and all(g[k][c]==0 for k in range(r+1,r2)):
                for k in range(r+1,r2): o[k][c]=1
                break
            if g[r2][c]!=0: break
    return o
